38: /**
39:  * This class is based on "jvmps" class from jvmps 2.0 written by Brian Doherty.
40:  * It provides functionality to identify all the JVMs currently running on the local machine.
41:  * Comments starting with //// are original comments from Brian.
42:  *
43:  * @author Tomas Hurka
44:  * @author Misha Dmitriev
45:  */
46: public class JpsProxy {
47: 
48:     //~ Methods ------------------------------------------------------------------------------------------------------------------
49: 
50:     /** Returns the array of records for all running VMs capable of dynamic attach (JDK 1.6 and newer)*/
51:     public static RunningVM[] getRunningVMs() {
52:         String hostname = null;
53:         List vret = new ArrayList();
54: 
55:         try {
56:             HostIdentifier hostId = new HostIdentifier(hostname);
57:             MonitoredHost monitoredHost = MonitoredHost.getMonitoredHost(hostId);
58:             String selfName = ManagementFactory.getRuntimeMXBean().getName();
59: 
60:             //// get the list active VMs on the specified host.
61:             Set jvms = monitoredHost.activeVms();
62: 
63:             if (jvms.isEmpty()) {
64:                 return null;
65:             }
66: 
67:             for (Iterator j = jvms.iterator(); j.hasNext();) {
68:                 int lvmid = ((Integer) j.next()).intValue();
69: 
70:                 if (selfName.startsWith(lvmid + "@")) { // myself
71: 
72:                     continue;
73:                 }
74: 
75:                 VmIdentifier id = null;
76:                 MonitoredVm vm = null;
77:                 String uriString = "//" + lvmid + "?mode=r"; // NOI18N
78: 
79:                 try {
80:                     id = new VmIdentifier(uriString);
81:                     vm = monitoredHost.getMonitoredVm(id, 0);
82:                 } catch (URISyntaxException e) {
83:                     //// this error should not occur as we are creating our own VMIdentifiers above based on a validated HostIdentifier.
84:                     //// This would be an unexpected condition.
85:                     MiscUtils.printWarningMessage("in jvmps, detected malformed VM Identifier: " + uriString + "; ignored"); // NOI18N
86: 
87:                     continue;
88:                 } catch (MonitorException e) {
89:                     System.out.println("Ex " + e.getMessage());
90:                     e.printStackTrace();
91: 
92:                     //// it's possible that from the time we acquired the list of available jvms that a jvm has terminated. Therefore, it is
93:                     //// best just to ignore this error.
94:                     continue;
95:                 } catch (Exception e) {
96:                     //// certain types of errors, such as access acceptions, can be encountered when attaching to a jvm.
97:                     //// These are reported as exceptions, not as some subclass of security exception.
98: 
99:                     //// FIXME - we should probably have some provision for logging these types of errors, or possibly just print out the
100:                     //// the Java Virtual Machine lvmid in a finally clause: System.out.println(String.valueOf(lvmid));
101:                     MiscUtils.printWarningMessage("in jvmps, for VM = " + String.valueOf(lvmid) + " got exception: " + e); // NOI18N
102: 
103:                     continue;
104:                 }
105: 
106:                 if (!isAttachable(vm)) {
107:                     monitoredHost.detach(vm);
108: 
109:                     continue;
110:                 }
111: 
112:                 String cmdString = MonitoredVmUtil.commandLine(vm);
113:                 String mainClass = MonitoredVmUtil.mainClass(vm, true);
114:                 String mainArgs = MonitoredVmUtil.mainArgs(vm);
115:                 String vmArgs = MonitoredVmUtil.jvmArgs(vm);
116:                 String vmFlags = MonitoredVmUtil.jvmFlags(vm);
117: 
118:                 monitoredHost.detach(vm);
119: 
120:                 RunningVM rvm = new RunningVM(lvmid, vmFlags, vmArgs, mainClass, mainArgs);
121:                 vret.add(rvm);
122:             }
123:         } catch (MonitorException e) {
124:             String report = "in jvmps, got MonitorException"; // NOI18N
125: 
126:             if (e.getMessage() != null) {
127:                 report += (" with message + " + e.getMessage()); // NOI18N
128:             }
129: 
130:             MiscUtils.printWarningMessage(report);
131: 
132:             return null;
133:         } catch (URISyntaxException e) {
134:             MiscUtils.printWarningMessage("in jvmps, got malformed Host Identifier: " + hostname); // NOI18N
135: 
136:             return null;
137:         }
138: 
139:         return (RunningVM[]) vret.toArray(new RunningVM[0]);
140:     }
141: 
142:     private static boolean isAttachable(MonitoredVm vm) {
143:         try {
144:             return MonitoredVmUtil.isAttachable(vm);
145:         } catch (MonitorException ex) {
146:             ex.printStackTrace();
147:             return false;
148:         }
149:     }
150: }

