123:     public static void main(String[] args) {
124:         boolean inDevelMode;
125: 
126:         if ((args.length > 0) && args[0].equals("-develmode")) { // NOI18N  // Development mode, see above
127:             inDevelMode = true;
128:             System.out.println("Loader for this class is " + ProfilerCalibrator.class.getClassLoader()); // NOI18N
129:         } else {
130:             inDevelMode = false;
