142: 
143:         measureBCIOverhead(inDevelMode);
144: 
145:         if (!inDevelMode) {
146:             if (!CalibrationDataFileIO.saveCalibrationData(status)) {
147:                 System.err.println(MessageFormat.format(CANNOT_SAVE_CALIBRATION_DATA_MSG,
148:                                                         new Object[] { CalibrationDataFileIO.getErrorMessage() }));
149:                 System.exit(-1);
150:             }
151: 
152:             System.out.println(CALIBRATION_SUCCESS_MSG);
153:             System.out.println(CALIBRATION_RESULTS_PREFIX);
154: 
155:             NumberFormat nf = NumberFormat.getInstance();
156:             nf.setMaximumFractionDigits(4);
157: 
158:             long cntsInSec = status.timerCountsInSecond[0];
159:             double m0 = (((double) status.methodEntryExitCallTime[0]) * 1000000) / cntsInSec; // Expressed in microseconds
160:             double m1 = (((double) status.methodEntryExitCallTime[1]) * 1000000) / cntsInSec; // Ditto
161:             double m2 = (((double) status.methodEntryExitCallTime[2]) * 1000000) / cntsInSec; // Ditto
162:             double m4 = (((double) status.methodEntryExitCallTime[4]) * 1000000) / cntsInSec; // Ditto
163: 
164:             StringBuilder s = new StringBuilder();
165:             s.append(MessageFormat.format(CALIBRATION_RESULTS_MSG,
166:                                           new Object[] { nf.format(m0), nf.format(m1), nf.format(m2), nf.format(m4) }));
167: 
168:             System.out.println(s.toString());
169:         }
