172:     /**
173:      * In addition to calculating and optionally printing some measurements of the overhead imposed by BCI, this
174:      * call, I hope,  makes the impact of BCI on the target application more uniform/predictable, since it causes
175:      * the VM to precompile various profiling calls.
176:      */
177:     public static void measureBCIOverhead(boolean printRes) {
178:         printResults = printRes;
179: 
180:         System.out.println(STARTING_CALIBRATION_MSG);
181: 
182:         // Just wait for some time, to e.g. make caller threads finish their work, etc.
183:         try {
184:             Thread.sleep(1000);
185:         } catch (Exception ex) {
186:         }
187: 
188:         cntInSecond = Timers.getNoOfCountsInSecond();
189:         printResults(MessageFormat.format(TIMER_COUNTS_MSG, new Object[] { "" + cntInSecond })); // NOI18N
190:         printResults(MessageFormat.format(TIMER_VALUE_MSG, new Object[] { "" + Timers.getCurrentTimeInCounts() })); // NOI18N
191: 
192:         if (status != null) {
193:             status.timerCountsInSecond = new long[2];
194:             status.timerCountsInSecond[0] = cntInSecond;
195:             status.timerCountsInSecond[1] = 1000000000;
196:         }
197: 
198:         ProfilerRuntime.resetProfilerCollectors(INSTR_RECURSIVE_FULL);
199:         ProfilerRuntimeCPU.setNProfiledThreadsLimit(1);
200:         ProfilerRuntimeCPU.setInstrMethodsInvoked(new boolean[] { true, true, true, true });
201:         ProfilerRuntimeCPU.createThreadInfoForCurrentThread();
202: 
203:         printResults(INJECTION_CALIBRATION_MSG + "\n"); // NOI18N
204: 
205:         if (printResults) { // Measure and print the performance of getCurrentTimeInCounts() - for information only
206:             measureTimerCall(true);
207:             measureTimerCall(false);
208:         }
209: 
210:         //deviation = 0; nDevSamples = 0;
211:         nCall = -1;
212:         measureMethodEntryExitCalls(); // A warmup run to make the compiler make all necessary inlines etc.
213: 
214:         for (nCall = 0; nCall < 4; nCall++) {
215:             measureMethodEntryExitCalls(); // This knows what to count depending on nCall
216: 
217:             if (status != null) {
218:                 status.methodEntryExitCallTime[nCall] = minTimePerMethodEntryExitCallInCounts;
219:                 status.methodEntryExitInnerTime[nCall] = innerTimeInCounts;
220:                 status.methodEntryExitOuterTime[nCall] = outerTimeInCounts;
221:             }
222:         }
223: 
224:         //deviation /= nDevSamples; System.out.println("**! deviation = " + deviation);
225: 
226:         //if (printResults) {                             // For information purposes only
227:         //  measureUnsuccessfulMethodEntryExitCalls();  
228:         //  measureSuccessfulMethodEntryExitCallsCalledFromInterpreted();
229:         //}
230:         nCall = -1;
231:         measureSampledMethodEntryExitCalls(); // Again a warmup run
232:         nCall = 0;
233:         measureSampledMethodEntryExitCalls();
234: 
235:         if (status != null) {
236:             status.methodEntryExitCallTime[4] = minTimePerMethodEntryExitCallInCounts;
237:             status.methodEntryExitInnerTime[4] = innerTimeInCounts;
238:             status.methodEntryExitOuterTime[4] = outerTimeInCounts;
239:         }
240: 
241:         measureCodeRegionCalls();
242: 
243:         printResults("----------------------------------------------------------\n"); // NOI18N
244: 
245:         buf = null;
246:         ProfilerRuntimeCPUCodeRegion.setCPUResBufSize(0);
247:         ThreadInfo.setDefaultEvBufParams();
248:         ProfilerRuntime.resetProfilerCollectors(INSTR_RECURSIVE_FULL);
249:         ProfilerRuntime.resetProfilerCollectors(INSTR_RECURSIVE_SAMPLED);
250:     }
