285:     private static void measureCodeRegionCalls() {
286:         printResults("\n" + REGION_TIME_MSG); // NOI18N
287:         ProfilerRuntimeCPUCodeRegion.setCPUResBufSize(100);
288:         ProfilerRuntimeCPUCodeRegion.resetProfilerCollectors();
289: 
290:         int noOfInnerIterations = 50;
291: 
292:         for (int i = 0; i < 50; i++) {
293:             long time = Timers.getCurrentTimeInCounts();
294: 
295:             for (int j = 0; j < noOfInnerIterations; j++) {
296:                 ProfilerRuntimeCPUCodeRegion.codeRegionEntry();
297:                 ProfilerRuntimeCPUCodeRegion.codeRegionExit();
298:                 ProfilerRuntimeCPUCodeRegion.codeRegionEntry();
299:                 ProfilerRuntimeCPUCodeRegion.codeRegionExit();
