98: /*
99:  * This routine updates the bootstrap class path (if necessary) and then calls
100:  * ProfilerServer.activate() method.
101:  * The activateCode parameter signals the type of attachment to the ProfilerServer:
102:  *   0 - dynamic attachment (not used so far), 1 - attach on startup
103:  */
104: static jint setupAndCallProfilerRuntimeActivate(JNIEnv *env, jint activateCode) {
105:     jmethodID activateMethodID;
106:     jclass profilerServerClass;
107:     jstring jfluidDir;
108: 
109:     /* For some reason (null classloader?) have to use slashed name - it barks if it is dotted */
110:     profilerServerClass = (*env)->FindClass(env, "org/graalvm/visualvm/lib/jfluid/server/ProfilerServer");
111:     if (profilerServerClass == NULL) {
112:         char *new_sun_boot_class_path;
113:         (*_jvmti)->GetSystemProperty(_jvmti, "sun.boot.class.path", &new_sun_boot_class_path);
114:         fprintf(stderr, "Profiler Agent Error: Can't start the profiler back end: main class not found\n");
115:         fprintf(stderr, "Profiler Agent Error: Boot class path was set to: %s\n", new_sun_boot_class_path);
116:         (*_jvmti)->Deallocate(_jvmti, (void*)new_sun_boot_class_path);
117:         fprintf(stderr, "Profiler Agent Error: Please check if you have jfluid-server.jar on this path\n");
118:         return -1;
119:     }
120: 
121:     activateMethodID = (*env)->GetStaticMethodID(env, profilerServerClass, "activate", "(Ljava/lang/String;III)V");
122:     if (activateMethodID == NULL) {
123:         fprintf(stderr, "Profiler Agent Error: Can't start the profiler back end: activate(String, int) method not found in main class\n");
124:         return -1;
125:     }
126: 
127:     jfluidDir = (*env)->NewStringUTF(env, _jfluid_dir);
128: 
129:     (*env)->CallStaticVoidMethod(env, profilerServerClass, activateMethodID, jfluidDir, _port_no, activateCode, _time_out);
130: 
131:     (*env)->DeleteLocalRef(env, jfluidDir);
132:     (*env)->DeleteLocalRef(env, profilerServerClass);
133:     if ((*env)->ExceptionCheck(env)) {
134:         (*env)->ExceptionDescribe(env);
135:         return -1;
136:     }
137: 
138:     return 0;
139: }
