79: int VisualVMLauncher::start(int argc, char *argv[]) {
80:     SetErrorMode(SetErrorMode(0) | SEM_FAILCRITICALERRORS | SEM_NOOPENFILEERRORBOX);
81:     
82:     DWORD parentProcID = 0;
83:     if (!checkLoggingArg(argc, argv, true) || !setupProcess(argc, argv, parentProcID, CON_ATTACH_MSG) || !initBaseNames() || !readClusterFile()) {
84:         return -1;
85:     }
86: 
87:     parseConfigFile((baseDir + "\\etc\\" + getAppName() + ".conf").c_str());
88: 
89:     if (!parseArgs(argc, argv)) {
90:         return -1;
91:     }
92:     string oldUserDir = userDir;
93:     parseConfigFile((userDir + "\\etc\\" + getAppName() + ".conf").c_str());
94:     userDir = oldUserDir;
95: 
96:     adjustHeapSize();
97:     addExtraClusters();
98:     string nbexecPath;
99:     SetDllDirectory(baseDir.c_str());
100:     if (dirExists(platformDir.c_str())) {
101:         nbexecPath = platformDir;
102:     } else {
103:         nbexecPath = baseDir + '\\' + platformDir;
104:     }
105:     if (!dirExists(nbexecPath.c_str())) {
106:         logErr(false, true, "Could not find platform cluster:\n%s", nbexecPath.c_str());
107:         return false;
108:     }
109: 
110:     CmdArgs newArgs(argc + 20);
111:     addSpecificOptions(newArgs);
112:     
113:     if (!clusters.empty()) {
114:         newArgs.add(ARG_NAME_CLUSTERS);
115:         newArgs.add(clusters.c_str());
116:     }
117:     if (!userDir.empty()) {
118:         newArgs.add(ARG_NAME_USER_DIR);
119:         newArgs.add(userDir.c_str());
120:     }
121:     if (!defUserDirRoot.empty()) {
122:         newArgs.add(ARG_DEFAULT_USER_DIR_ROOT);
123:         newArgs.add(defUserDirRoot.c_str());
124:     }
125:     if (!cacheDir.empty() && !customUserDirFound) {
126:         newArgs.add(ARG_NAME_CACHE_DIR);
127:         newArgs.add(cacheDir.c_str());
128:     }
129:     if (!nbOptions.empty()) {
130:         newArgs.addCmdLine(nbOptions.c_str());
131:     }
132:     for (int i = 0; i < argc; i++) {
133:         newArgs.add(argv[i]);
134:     }
135:     if (!jdkOptionFound && jdkHome.empty()) {
136:         if (jvmFinder.findJava(REQ_JAVA_VERSION)) {
137:             jvmFinder.getJavaPath(jdkHome);
138:         }
139:     }
140:     if (!jdkHome.empty()) {
141:         newArgs.add(ARG_NAME_JDKHOME);
142:         newArgs.add(jdkHome.c_str());
143:     }
144:     if (parentProcID) {
145:         newArgs.add(ARG_NAME_LA_PPID);
146:         char tmp[16] = "";
147:         newArgs.add(itoa(parentProcID, tmp, 10));
148:     }
149:     nbexecPath += NBEXEC_FILE_PATH;
150: 
151:     const char *curDir = getCurrentDir();
152:     if (curDir) {
153:         char olddir[MAX_PATH];
154:         DWORD rc = GetCurrentDirectory(MAX_PATH, olddir);
155:         if (rc == 0) {
156:             logErr(true, false, "Failed to get current directory");
157:         } else {
158:             string od = string(olddir);
159:             od.insert(0, "-J-Dnetbeans.user.dir=");
160:             newArgs.add(od.c_str());
161:         }
162:         logMsg("Changing current directory to: \"%s\"", curDir);
163:         SetCurrentDirectory(curDir);
164:     }
165: 
166:     NBExecLoader loader;
167:     return loader.start(nbexecPath.c_str(), newArgs.getCount(), newArgs.getArgs());
168: }
