209: void VisualVMLauncher::addCluster(const char *cluster) {
210: 
211:     class SetCurDir {
212:     public:
213:         SetCurDir(const char *dir) {
214:             oldCurDir[0] = '\0';
215:             DWORD rc = GetCurrentDirectory(MAX_PATH, oldCurDir);
216:             if (rc == 0) {
217:                 logErr(true, false, "Failed to get current directory");
218:                 return;
219:             }
220:             if (rc > MAX_PATH) {
221:                 logMsg("Failed to get current directory, buffer is too small.");
222:                 return;
223:             }
224:             if (!SetCurrentDirectory(dir)) {
225:                 logErr(true, true, "Failed to set current directory to \"%s\"", dir);
226:                 oldCurDir[0] = '\0';
227:             }
228:         }
229: 
230:         ~SetCurDir() {
231:             if (oldCurDir[0]) {
232:                 if (!SetCurrentDirectory(oldCurDir)) {
233:                     logErr(true, true, "Failed to set current directory to \"%s\"", oldCurDir);
234:                 }
235:             }
236:         }
237:     private:
238:         char oldCurDir[MAX_PATH];
239:     };
240: 
241:     logMsg("addCluster: %s", cluster);
242:     SetCurDir setCurDir(baseDir.c_str());
243:     char clusterPath[MAX_PATH + 1] = {0};
244:     strncpy(clusterPath, cluster, MAX_PATH);
245:     if (!normalizePath(clusterPath, MAX_PATH)) {
246:         logMsg("Invalid cluster path: %s", cluster);
247:         return;
248:     }
249:     if (!clusters.empty()) {
250:         clusters += ';';
251:     }
252:     logMsg("Adding cluster %s", clusterPath);
253:     clusters += clusterPath;
254: }
