256: void VisualVMLauncher::addExtraClusters() {
257:     logMsg(__PRETTY_FUNCTION__);
258:     const char delim = ';';
259:     string::size_type start = extraClusters.find_first_not_of(delim, 0);
260:     string::size_type end = extraClusters.find_first_of(delim, start);
261:     while (string::npos != end || string::npos != start) {
262:         string cluster = extraClusters.substr(start, end - start);
263:         addCluster(cluster.c_str());
264:         start = extraClusters.find_first_not_of(delim, end);
265:         end = extraClusters.find_first_of(delim, start);
266:     }
267: }
