269: bool VisualVMLauncher::readClusterFile() {
270:     clusters = "";
271:     string clusterFile = baseDir + "\\etc\\" + getAppName() + ".clusters";
272:     logMsg("readClusterFile() file: %s", clusterFile.c_str());
273: 
274:     FILE* file = fopen(clusterFile.c_str(), "r");
275:     if (!file) {
276:         logErr(true, true, "Cannot open file \"%s\" for reading.", clusterFile.c_str());
277:         return false;
278:     }
279: 
280:     char line[4096] = "";
281:     while (fgets(line, sizeof(line), file)) {
282:         char *str = skipWhitespaces(line);
283:         if (*str == '#' || *str == '\0') {
284:             continue;
285:         }
286:         char *pc = str;
287:         while (*pc != '\0' && *pc != '\t' && *pc != '\n' && *pc != '\r') {
288:             pc++;
289:         }
290:         *pc = '\0';
291: 
292:         if (platformDir.empty()) {
293:             char *slash = strrchr(str, '\\');
294:             if (!slash) {
295:                 slash = strrchr(str, '/');
296:             }
297:             char *dir = slash ? slash + 1 : str;
298:             if (strncmp(dir, "platform", strlen("platform")) == 0) {
299:                 platformDir = str;
300:             } else {
301:                 addCluster(str);
302:             }
303:         } else {
304:             addCluster(str);
305:         }
306:     }
307:     bool ok = ferror(file) == 0;
308:     if (!ok) {
309:         logErr(true, true, "Error while reading file \"%s\".", clusterFile.c_str());
310:     }
311:     fclose(file);
312:     if (platformDir.empty()) {
313:         platformDir = "platform";
314:     }
315:     return ok;
316: }
