363: bool VisualVMLauncher::findUserDir(const char *str) {
364:     logMsg(__PRETTY_FUNCTION__);
365:     if (strncmp(str, HOME_TOKEN, strlen(HOME_TOKEN)) == 0) {
366:         if (userHome.empty()) {
367:             char *userProfile = getenv(ENV_USER_PROFILE);
368:             if (userProfile) {
369:                 userHome = userProfile;
370:             } else {
371:                 TCHAR userHomeChar[MAX_PATH]; 
372:                 if (FAILED(SHGetFolderPath(NULL, CSIDL_DESKTOP, NULL, 0, userHomeChar))) {    
373:                     return false;
374:                 }
375:                 userHome = userHomeChar;
376:                 userHome.erase(userHome.rfind('\\'));
377:             }
378:             logMsg("User home: %s", userHome.c_str());
379:         }
380:         userDir = userHome + (str + strlen(HOME_TOKEN));
381:     } else if (strncmp(str, DEFAULT_USERDIR_ROOT_TOKEN, strlen(DEFAULT_USERDIR_ROOT_TOKEN)) == 0) {       
382:         userDir = getDefaultUserDirRoot() + (str + strlen(DEFAULT_USERDIR_ROOT_TOKEN));
383:     } else {
384:         getDefaultUserDirRoot();
385:         userDir = str;
386:     }
387:     return true;
388: }
