455: bool VisualVMLauncher::parseConfigFile(const char* path) {
456:     logMsg("parseConfigFile(%s)", path);
457:     FILE *file = fopen(path, "r");
458:     if (!file) {
459:         logErr(true, false, "Cannot open file \"%s\" for reading.", path);
460:         return false;
461:     }
462:     
463:     char line[4096] = "";
464:     while (fgets(line, sizeof(line), file)) {
465:         char *str = skipWhitespaces(line);
466:         if (*str == '#') {
467:             continue;
468:         }
469:         if (getOption(str, getDefUserDirOptName())) {
470:              findUserDir(str);
471:              logMsg("User dir: %s", userDir.c_str());
472:         } else if (getOption(str, getDefCacheDirOptName())) {
473:              findCacheDir(str);
474:              logMsg("Cache dir: %s", cacheDir.c_str());
475:         } else if (getOption(str, getDefOptionsOptName())) {
476:             // replace \" by "
477:             int len = strlen(str);
478:             int k = 0;
479:             for (int i = 0; i < len; i++) {
480:                 if (str[i] == '\\' && str[i+1] == '\"') {
481:                     continue;
482:                 }
483:                 str[k++] = str[i];
484:             }
485:             str[k] = '\0';
486:             nbOptions = str;
487:             logMsg("After replacement: %s", nbOptions.c_str());
488: 
489:         } else if (getOption(str, getExtraClustersOptName())) {
490:             extraClusters = str;
491:         } else if (getOption(str, getJdkHomeOptName())) {
492:             jdkHome = str;
493:         }
494:     }
495:     bool ok = ferror(file) == 0;
496:     if (!ok) {
497:         logErr(true, false, "Error while reading file \"%s\".", path);
498:     }
499:     fclose(file);
500:     return true;
501: }
