505: bool VisualVMLauncher::areWeOn32bits() {
506:     // find out if we are on 32-bit Windows
507:     SYSTEM_INFO siSysInfo;
508:     PGNSI pGNSI;
509:     pGNSI = (PGNSI) GetProcAddress(GetModuleHandle(TEXT("kernel32.dll")),
510:             "GetNativeSystemInfo");
511:     if (NULL != pGNSI)
512:         pGNSI(&siSysInfo);
513:     else
514:         GetSystemInfo(&siSysInfo);
515:     logMsg("VisualVMLauncher::areWeOn32bits returns (0=false, 1=true)? %i", ((siSysInfo.wProcessorArchitecture == PROCESSOR_ARCHITECTURE_INTEL) ||
516:             (strstr(NBEXEC_FILE_PATH, "64") == NULL)));
517:     return ((siSysInfo.wProcessorArchitecture == PROCESSOR_ARCHITECTURE_INTEL) ||
518:             (strstr(NBEXEC_FILE_PATH, "64") == NULL));
519: }
