521: // Search if -Xmx is specified in existing arguments
522: // If it isn't compute default values based on 32/64-bits and available RAM
523: void VisualVMLauncher::adjustHeapSize() {
524:     if (nbOptions.find("-J-Xmx") == string::npos) {
525:         int maxheap;
526:         if (areWeOn32bits())
527:             maxheap = 512;
528:         else
529:             maxheap = 1024;
530:         // find how much memory we have and add -Xmx as 1/5 of the memory
531:         MEMORYSTATUSEX ms = {0};
532:         ms.dwLength = sizeof (ms);
533:         GlobalMemoryStatusEx(&ms);
534:         int memory = (int)((ms.ullTotalPhys / 1024 / 1024) / 5);
535:         if (memory < 96) {
536:             memory = 96;
537:         }
538:         else if (memory > maxheap) {
539:             memory = maxheap;
540:         }
541:         char tmp[32];
542:         snprintf(tmp, 32, " -J-Xmx%dm", memory);
543:         logMsg("Memory settings: -J-Xmx%dm", memory);
544:         nbOptions += tmp;
545:     }
546: }
