106: jint convert_JVMTI_thread_status_to_jfluid_status(jint jvmtiThreadStatus) {
107:     jint status = jvmtiThreadStatus & JF_THREAD_STATE_MASK;
108:   
109:     if      (status == JF_THREAD_STATE_RUNNABLE)      return THREAD_STATUS_RUNNING;
110:     else if (status == JF_THREAD_STATE_BLOCKED)       return THREAD_STATUS_MONITOR;
111:     else if (status == JF_THREAD_STATE_WAITING)       return THREAD_STATUS_WAIT;
112:     else if (status == JF_THREAD_STATE_TIMED_WAITING) return THREAD_STATUS_WAIT;
113:     else if (status == JF_THREAD_STATE_PARKED)        return THREAD_STATUS_PARK;
114:     else if (status == JF_THREAD_STATE_TIMED_PARKED)  return THREAD_STATUS_PARK;
115:     else if (status == JF_THREAD_STATE_SLEEPING)      return THREAD_STATUS_SLEEPING;
116:     else if (status == JF_THREAD_STATE_NEW)           return THREAD_STATUS_ZOMBIE;
117:     else if (status == JF_THREAD_STATE_TERMINATED)    return THREAD_STATUS_ZOMBIE;
118:     else                                              return THREAD_STATUS_UNKNOWN;
