1: #!/usr/bin/env node
2: /**
3:  * CLI over web/harmony-mirror.js — check if packages are adapted to HarmonyOS PC,
4:  * or stamp a report.json's dependencies in place. Used by the analyzer agent:
5:  *   node scripts/harmony_adapted.js --report runs/<lib>/<ts>/report.json
6:  *   node scripts/harmony_adapted.js --ecosystem python --names numpy,scipy
7:  */
8: 'use strict';
9: 
10: const mirror = require('../web/harmony-mirror');
11: 
12: function arg(name, def) {
13:   const i = process.argv.indexOf(name);
14:   return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : def;
15: }
16: 
17: (async () => {
18:   const report = arg('--report');
19:   if (report) {
20:     const r = await mirror.stampReport(report);
21:     console.log(`stamped ${r.stamped}/${r.total} dependencies as harmony_adapted in ${report}`);
22:     return;
23:   }
