223:     private void printThreads(final StringBuilder sb, final ThreadMXBean threadMXBean, ThreadInfo[] threads) {
224:         boolean jdk16 = hasDumpAllThreads();
225:         
226:         for (ThreadInfo thread : threads) {
227:             if (thread != null) {
228:                 if (jdk16) {
229:                     print16Thread(sb, threadMXBean, thread);
230:                 } else {
231:                     print15Thread(sb, thread);
232:                 }
233:             }
234:         }
