237:     private void print16Thread(final StringBuilder sb, final ThreadMXBean threadMXBean, final ThreadInfo thread) {
238:         MonitorInfo[] monitors = null;
239:         if (threadMXBean.isObjectMonitorUsageSupported()) {
240:             monitors = thread.getLockedMonitors();
241:         }
242:         sb.append("\n\"" + thread.getThreadName() + // NOI18N
243:                 "\" - Thread t@" + thread.getThreadId() + "\n");    // NOI18N
244:         sb.append("   java.lang.Thread.State: " + thread.getThreadState()); // NOI18N
245:         sb.append("\n");   // NOI18N
246:         int index = 0;
247:         for (StackTraceElement st : thread.getStackTrace()) {
248:             LockInfo lock = thread.getLockInfo();
249:             String lockOwner = thread.getLockOwnerName();
250:             
251:             sb.append("\tat " + st.toString() + "\n");    // NOI18N
252:             if (index == 0) {
253:                 if ("java.lang.Object".equals(st.getClassName()) &&     // NOI18N
254:                         "wait".equals(st.getMethodName())) {                // NOI18N
255:                     if (lock != null) {
256:                         sb.append("\t- waiting on ");    // NOI18N
257:                         printLock(sb,lock);
258:                         sb.append("\n");    // NOI18N
259:                     }
260:                 } else if (lock != null) {
261:                     if (lockOwner == null) {
262:                         sb.append("\t- parking to wait for ");      // NOI18N
263:                         printLock(sb,lock);
264:                         sb.append("\n");            // NOI18N
265:                     } else {
266:                         sb.append("\t- waiting to lock ");      // NOI18N
267:                         printLock(sb,lock);
268:                         sb.append(" owned by \""+lockOwner+"\" t@"+thread.getLockOwnerId()+"\n");   // NOI18N
269:                     }
270:                 }
271:             }
272:             printMonitors(sb, monitors, index);
273:             index++;
274:         }
275:         StringBuilder jnisb = new StringBuilder();
276:         printMonitors(jnisb, monitors, -1);
277:         if (jnisb.length() > 0) {
278:             sb.append("   JNI locked monitors:\n");
279:             sb.append(jnisb);
280:         }
281:         if (threadMXBean.isSynchronizerUsageSupported()) {
282:             sb.append("\n   Locked ownable synchronizers:");    // NOI18N
283:             LockInfo[] synchronizers = thread.getLockedSynchronizers();
284:             if (synchronizers == null || synchronizers.length == 0) {
285:                 sb.append("\n\t- None\n");  // NOI18N
286:             } else {
287:                 for (LockInfo li : synchronizers) {
288:                     sb.append("\n\t- locked ");         // NOI18N
289:                     printLock(sb,li);
290:                     sb.append("\n");  // NOI18N
291:                 }
292:             }
293:         }
294:     }
295: 
296:     private void printMonitors(final StringBuilder sb, final MonitorInfo[] monitors, final int index) {
297:         if (monitors != null) {
298:             for (MonitorInfo mi : monitors) {
299:                 if (mi.getLockedStackDepth() == index) {
300:                     sb.append("\t- locked ");   // NOI18N
301:                     printLock(sb,mi);
302:                     sb.append("\n");    // NOI18N
303:                 }
304:             }
305:         }
306:     }
