308:     private void print15Thread(final StringBuilder sb, final ThreadInfo thread) {
309:         sb.append("\n\"" + thread.getThreadName() + // NOI18N
310:                 "\" - Thread t@" + thread.getThreadId() + "\n");    // NOI18N
311:         sb.append("   java.lang.Thread.State: " + thread.getThreadState()); // NOI18N
312:         if (thread.getLockName() != null) {
313:             sb.append(" on " + thread.getLockName());   // NOI18N
314:             if (thread.getLockOwnerName() != null) {
315:                 sb.append(" owned by: " + thread.getLockOwnerName());   // NOI18N
316:             }
317:         }
318:         sb.append("\n");    // NOI18N
319:         for (StackTraceElement st : thread.getStackTrace()) {
320:             sb.append("        at " + st.toString() + "\n");    // NOI18N
321:         }
322:     }
